"""Build a searchable browser for side sub-icons and container symbols."""
from pathlib import Path
import csv,json,os
ROOT=Path(__file__).resolve().parents[2]
def main():
 d=json.loads((ROOT/'icon_set/model/catalog/sub-usage-categories.json').read_text());out=ROOT/'icon_set/work/sub-symbol-categories';out.mkdir(exist_ok=True);items=[]
 for e in d['icons']:
  for role,v in e['versions'].items():
   items.append(dict(group=e['related_group'],original=e['original_icon_id'],role=role,icon=v['icon_id'],shared=e['usage']=='both',pairs=len(e['pair_ids'][role]),status=v['model_validation'],model=os.path.relpath(ROOT/v['python_source'],out),svg=(ROOT/v['svg']).read_text(),counterpart=next((x['icon_id'] for k,x in e['versions'].items() if k!=role),None)))
 with (out/'categories.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['original','role','icon','shared','pairs','status','model','counterpart']);w.writeheader();w.writerows({k:r[k] for k in w.fieldnames} for r in items)
 template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Side sub-icons & container symbols</title><style>*{box-sizing:border-box}body{font:15px system-ui;background:#f5f7fa;color:#243147;margin:28px}p{line-height:1.6}a{color:#275baf}nav{position:sticky;top:0;background:#f5f7fa;padding:12px 0;z-index:2;display:flex;flex-wrap:wrap;gap:10px}button,select,input{font:inherit;padding:9px;border:1px solid #becbd9;border-radius:7px;background:white}button{cursor:pointer}.metrics{display:flex;gap:14px;flex-wrap:wrap}.metric,article{background:white;border:1px solid #d7e0e9;border-radius:12px;padding:18px}.metric strong{display:block;font-size:28px}main{display:grid;grid-template-columns:repeat(auto-fill,minmax(235px,1fr));gap:14px}article h2{font-size:14px;overflow-wrap:anywhere}article .art{height:100px;display:flex;align-items:center;justify-content:center;overflow:auto}svg{height:64px;width:auto;max-width:100%;color:#202630}small{display:block;color:#67768b;margin:8px 0}article a{display:block;margin:6px 0;font-size:13px}article button{font-size:13px}header{max-width:1120px}.badge{color:#285c87;font-size:12px}.bar{display:flex;gap:14px;align-items:center;margin:15px 0}</style><header><h1>Side sub-icons & container symbols</h1><div class="metrics"><div class="metric"><strong>825</strong>Side sub-icons</div><div class="metric"><strong>1,004</strong>Container symbols</div><div class="metric"><strong>293</strong>Linked pairs · independent drawings</div></div><p>532 originals are side-only, 711 are symbol-only, and 293 are used in both contexts. There are 1,536 distinct originals and 1,829 role-specific entries after separation.</p><p><b>Side sub-icon:</b> placed beside a main icon. <b>Symbol:</b> placed inside a container. Shared originals now have separate Python drawings; editing one does not update the other. Their shared origin and counterpart links remain recorded. These are actual Sub / SUB32 and Symbol / SYMBOL32 families. Both keep the same 32-unit geometric rules.</p><p>Counts follow actual mapped usage in 3,533 side and 2,709 container pair definitions. Pair references shown per asset count unique definitions using it. Unused library drawings are left unassigned.</p><p><a href="http://localhost:8000/gallery/index.html?tab=icons&amp;family=symbol">Manage Symbol family in the main gallery</a> · <a href="categories.csv">Download category list</a> · <a href="../../model/catalog/sub-usage-categories.json">Category and relationship manifest</a> · <a href="../container-pair-combinations/index.html">Container combinations</a></p></header><nav><select id="role"><option value="all">Both categories</option><option value="side">Side sub-icons</option><option value="symbol">Container symbols</option></select><select id="shared"><option value="all">All usage</option><option value="yes">Used in both · linked versions</option><option value="no">One category only</option></select><input id="query" placeholder="Search icon name"><button id="clear">Clear filters</button></nav><div class="bar"><button id="prev">Previous</button><span id="count"></span><button id="next">Next</button></div><main></main><script id="data" type="application/json">__DATA__</script><script>const D=JSON.parse(document.querySelector('#data').textContent),$=s=>document.querySelector(s);let page=0,group=null;function render(){let rows=D.filter(r=>($('#role').value==='all'||r.role===$('#role').value)&&($('#shared').value==='all'||r.shared===($('#shared').value==='yes'))&&(!group||r.group===group)&&((r.icon+' '+r.original).toLowerCase().includes($('#query').value.toLowerCase())));const total=Math.max(1,Math.ceil(rows.length/72));page=Math.max(0,Math.min(page,total-1));$('#count').textContent=rows.length+' entries · page '+(page+1)+' / '+total;$('#prev').disabled=page===0;$('#next').disabled=page===total-1;const main=$('main');main.replaceChildren();for(const r of rows.slice(page*72,(page+1)*72)){let card=document.createElement('article'),art=document.createElement('div');art.className='art';const xml=new DOMParser().parseFromString(r.svg,'image/svg+xml');art.append(document.importNode(xml.documentElement,true));card.append(art);let h=document.createElement('h2');h.textContent=r.icon;card.append(h);let b=document.createElement('div');b.className='badge';b.textContent=r.role==='symbol'?'Container symbol':'Side sub-icon';card.append(b);let note=document.createElement('small');note.textContent=r.pairs+' pair definitions · drawing status: '+r.status;card.append(note);let a=document.createElement('a');a.href=r.model;a.textContent='Independent editable model';card.append(a);if(r.shared){let button=document.createElement('button');button.textContent='Show linked versions';button.onclick=()=>{group=r.group;$('#role').value='all';$('#query').value='';page=0;render()};card.append(button);let link=document.createElement('small');link.textContent='Linked to '+r.counterpart;card.append(link)}main.append(card)}}for(const id of ['role','shared','query'])$('#'+id).addEventListener('input',()=>{page=0;group=null;render()});$('#clear').onclick=()=>{group=null;$('#query').value='';$('#role').value='all';$('#shared').value='all';render()};$('#prev').onclick=()=>{page--;render()};$('#next').onclick=()=>{page++;render()};render();</script></html>'''
 (out/'index.html').write_text(template.replace('__DATA__',json.dumps(items).replace('<','\\u003c')))
 print('Category browser:',out/'index.html')
if __name__=='__main__':main()
